"""The body templates (WUI slice 9a): the six bodies of the approved character designer mockup, which a new model can start from. Generated by
frontend/scripts/body-templates into app/seed/body_templates.json (bundled with the app like the basic model); read-only, so they are read once."""

import json
import sys
from functools import lru_cache
from pathlib import Path

from .schema import BodyTemplate, BodyTemplateInfo, BodyTemplateList, ModelContent, ModelGuide


class UnknownBodyTemplateError(KeyError):
    pass


def _path() -> Path:
    if hasattr(sys, "_MEIPASS"):
        return Path(sys._MEIPASS) / "app" / "seed" / "body_templates.json"  # type: ignore[attr-defined]
    return Path(__file__).resolve().parent.parent / "seed" / "body_templates.json"


@lru_cache(maxsize=1)
def _templates() -> tuple[BodyTemplate, ...]:
    try:
        raw = json.loads(_path().read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return ()
    out: list[BodyTemplate] = []
    for t in raw.get("templates", []) if isinstance(raw, dict) else []:
        try:
            content = ModelContent.model_validate(t["content"])
            guide = ModelGuide.model_validate(t["guide"]) if t.get("guide") is not None else None
            out.append(BodyTemplate(id=t["id"], name=t["name"], note=t.get("note", ""), heads=t.get("heads", 7.5), thumb=t.get("thumb", ""),
                                    content=content.model_copy(update={"guide": content.guide or guide})))
        except (KeyError, TypeError, ValueError):
            continue
    return tuple(out)


def list_templates() -> BodyTemplateList:
    """Every body template, without its content (its name, a note on the body, how many heads tall it stands and a small picture of it)."""
    return BodyTemplateList(templates=[BodyTemplateInfo(**t.model_dump(exclude={"content"})) for t in _templates()])


def get_template(template_id: str) -> BodyTemplate:
    """One body template with the model it starts (its shapes, rig and proportion guide). Raises UnknownBodyTemplateError."""
    for t in _templates():
        if t.id == template_id:
            return t
    raise UnknownBodyTemplateError(template_id)
